{
  "title": "渗透信息核心",
  "scene": "在一片灯火通明的赛博朋克都市中，天际线被霓虹灯渲染得五彩斑斓。街道两旁是巨大的广告牌和闪烁的霓虹招牌，偶尔有高速飞行的出租车掠过。你站在一个废弃的仓库前，这里是通往信息核心的入口。仓库的铁门半开，里面传来了奇怪的电子声。一个巨大的信息核心标志挂在仓库门口，上面闪烁着“系统核心”的字样。",
  "goal": "闯入信息核心并获取关键数据。",
  "choices": [
    {
      "id": "A",
      "text": "使用你的黑客设备尝试远程控制仓库大门。",
      "outcome": "设备未能成功解锁大门，但你注意到大门缝隙间有一块松动的砖块。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "寻找仓库周围是否有可以利用的工具或设备。",
      "outcome": "你在附近找到了一个看似能够制造干扰信号的设备。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "直接攀爬仓库外墙进入。",
      "outcome": "你在攀爬过程中被红外摄像头捕捉到，警报响起。安保人员迅速围了上来。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
